if(!UnityEditor.EditorApplication.isPlaying||string.IsNullOrEmpty(UnityEditor.SessionState.GetString("Bulldozer.Mining.TestSavePath","")))throw new System.Exception("Isolated Play required");
var p=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerController>();var e=p.visual.GetComponent<Bulldozer.Player.MinerEquipment>();var mining=p.visual.GetComponent<Bulldozer.Player.MinerMining>();var drops=e.drops;var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(UnityEngine.FindObjectsSortMode.None);var rock=rocks.First(r=>r.blockId=="quarry-v1-0-0");
var report=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,msg)=>report.Add((ok?"PASS ":"FAIL ")+msg);
System.Action<UnityEngine.Vector3> place=pos=>{p.CancelMining();p.touchControls.Move=UnityEngine.Vector2.zero;var motor=p.GetComponent<UnityEngine.CharacterController>();motor.enabled=false;p.transform.position=pos+UnityEngine.Vector3.up*.03f;motor.enabled=true;p.visual.rotation=UnityEngine.Quaternion.identity;UnityEngine.Physics.SyncTransforms();};
p.autoMine=true;place(rock.transform.position-UnityEngine.Vector3.forward*1.15f);float began=UnityEngine.Time.time,stageTime=began;int stage=0,firstFrame=UnityEngine.Time.frameCount;bool beganHit=false;int maxDust=0,maxChips=0;UnityEngine.Vector3 moveStart=UnityEngine.Vector3.zero;
UnityEditor.EditorApplication.CallbackFunction tick=null;System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;p.touchControls.Move=UnityEngine.Vector2.zero;p.autoMine=false;System.IO.File.WriteAllLines("Maintenance/Miner/arcade-mining-verification.txt",report);UnityEngine.Debug.Log(string.Join("\n",report));};
tick=()=>{
 if(!UnityEditor.EditorApplication.isPlaying||!p){UnityEditor.EditorApplication.update-=tick;return;}
 float now=UnityEngine.Time.time;maxDust=System.Math.Max(maxDust,drops.dust.particleCount);maxChips=System.Math.Max(maxChips,drops.chips.particleCount);
 if(now-began>25){check(false,"Timed out: stage="+stage+" health="+rock.Health+" mining="+p.IsMining+" hits="+mining.SuccessfulHits+" status="+mining.Status+" blocked="+p.InputBlocked);finish();return;}
 if(stage==0){if(!beganHit&&p.IsMining){check(rock.Health==rock.maxHealth,"Automatic mining starts without early damage");beganHit=true;}if(!rock.Depleted)return;
  check(beganHit&&mining.SuccessfulHits==3,"Three physical pickaxe contacts break the rock automatically");check(e.CargoCount==0&&e.Snapshot.groundDrops.Length==3&&drops.ActiveCount==3,"One broken rock produces three ground pieces, not instant cargo");check(maxDust>0&&maxChips>0,"Visible dust and stone chips emit on hits");
  var disk=new Bulldozer.Player.Persistence.MiningProgressStore(e.SavePath).Current;check(disk.groundDrops.Length==3&&disk.depletedBlocks.Contains(rock.blockId),"Rock depletion and all three uncollected pieces save together");p.autoMine=false;place(rock.transform.position);stage=1;stageTime=now;
 }else if(stage==1&&now-stageTime>1.5f){check(e.CargoCount==3&&e.Snapshot.groundDrops.Length==0,"Entering the pickup trigger collects all three pieces once");check(drops.ActiveCount==0,"Collected ore returns to the fixed pool");
  rock=rocks.First(r=>r.blockId=="quarry-v1-0-1");place(new UnityEngine.Vector3(-6,0,-3));e.SetCargoCount(4);for(int i=0;i<8&&!rock.Depleted;i++)rock.TryHit(e,rock.transform.position+UnityEngine.Vector3.up*.6f);place(rock.transform.position);stage=2;stageTime=now;
 }else if(stage==2&&now-stageTime>1.4f){check(e.CargoCount==5&&e.Snapshot.groundDrops.Length==2,"Full rack leaves excess ore on the ground");var disk=new Bulldozer.Player.Persistence.MiningProgressStore(e.SavePath).Current;check(disk.groundDrops.Length==2&&disk.cargo==5,"Remaining pickups survive a disk reload");e.SetCargoCount(0);rock=rocks.First(r=>r.blockId=="quarry-v1-0-3");place(rock.transform.position-UnityEngine.Vector3.forward*1.15f);p.autoMine=true;stage=3;stageTime=now;
 }else if(stage==3&&p.IsMining){moveStart=p.transform.position;p.touchControls.Move=UnityEngine.Vector2.left;stage=4;stageTime=now;
 }else if(stage==4&&now-stageTime>.3f){check(!p.IsMining&&UnityEngine.Vector3.Distance(moveStart,p.transform.position)>.3f,"Moving the joystick cancels mining and immediately moves the player");check(UnityEngine.Time.frameCount-firstFrame>60,"Real game frames advanced during automatic mining and pickup");check(drops.transform.childCount==98,"Ore and particle pool object count stays fixed");finish();}
};UnityEditor.EditorApplication.update+=tick;return "Automatic mining and pickup checks started";
